<?php
session_start();if(!isset($_SESSION['userName'])||$_SESSION['userName']!=='admin'){header('Location: alogin.php');exit;}require 'dbconfig.php';$message='';$type='';$cities=[];$q=$conn->query('SELECT DISTINCT City FROM clinic ORDER BY City');while($r=$q->fetch_assoc())$cities[]=$r['City'];$dayMap=['Monday'=>'Pazartesi','Tuesday'=>'Salı','Wednesday'=>'Çarşamba','Thursday'=>'Perşembe','Friday'=>'Cuma','Saturday'=>'Cumartesi','Sunday'=>'Pazar'];if(isset($_POST['Submit'])){$cid=(int)($_POST['clinic']??0);$did=(int)($_POST['doctor']??0);$start=$_POST['starttime']??'';$end=$_POST['endtime']??'';$days=$_POST['daylist']??[];$validDays=array_intersect(array_keys($dayMap),is_array($days)?$days:[]);if(!$cid||!$did||!$start||!$end||!$validDays){$message='Klinik, doktor, saat aralığı ve en az bir gün seçilmelidir.';$type='error';}elseif($start>=$end){$message='Başlangıç saati bitiş saatinden önce olmalıdır.';$type='error';}else{$conn->begin_transaction();try{$check=$conn->prepare('SELECT 1 FROM doctor_availability WHERE CID=? AND DID=? AND Day=? AND Starttime=? AND Endtime=? LIMIT 1');$ins=$conn->prepare('INSERT INTO doctor_availability (CID,DID,Day,Starttime,Endtime) VALUES (?,?,?,?,?)');$added=0;$skipped=0;foreach($validDays as $day){$check->bind_param('iisss',$cid,$did,$day,$start,$end);$check->execute();if($check->get_result()->num_rows){$skipped++;continue;}$ins->bind_param('iisss',$cid,$did,$day,$start,$end);if(!$ins->execute())throw new RuntimeException('insert');$added++;}$check->close();$ins->close();$conn->commit();$message=$added?'Program kaydedildi: '.$added.' gün eklendi.'.($skipped?' '.$skipped.' tekrar kayıt atlandı.':''):'Seçilen gün/saat kayıtları zaten mevcut.';$type=$added?'success':'error';}catch(Throwable $e){$conn->rollback();$message='Program kaydedilirken hata oluştu.';$type='error';}}}?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Doktor Programı | Appointment</title><link rel="stylesheet" href="adminmain.css"><style>.admin-wrap{width:min(900px,calc(100% - 32px));margin:30px auto 60px}.page-head{display:flex;justify-content:space-between;align-items:flex-end;gap:20px;margin-bottom:22px}.page-head h1{margin:5px 0 7px;font-size:32px}.page-head p{margin:0;color:var(--admin-muted)}.form-card{padding:24px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.full{grid-column:1/-1}.days{display:grid;grid-template-columns:repeat(4,1fr);gap:9px;margin-top:8px}.day{display:flex;align-items:center;gap:8px;padding:11px;border:1px solid var(--admin-border);border-radius:9px;font-size:12px;font-weight:750;cursor:pointer}.day input{width:auto}.form-actions{display:flex;justify-content:flex-end;gap:9px;margin-top:23px}.form-actions>*{width:auto}.hint{margin-top:6px;color:var(--admin-muted);font-size:11px}@media(max-width:650px){.admin-wrap{width:calc(100% - 20px);margin-top:18px}.page-head{align-items:flex-start;flex-direction:column}.page-head .admin-button{width:100%}.form-grid{grid-template-columns:1fr}.full{grid-column:auto}.days{grid-template-columns:1fr 1fr}.form-actions{display:grid;grid-template-columns:1fr}.form-actions>*{width:100%}}</style></head><body><header class="admin-topbar"><a class="admin-brand" href="mainpage.php"><img src="cal.png" alt="Appointment"><span>Appointment</span></a><nav class="admin-nav"><a href="mainpage.php">Panel</a><a href="showdoctor.php">Doktorlar</a><a class="active" href="adddoctorclinic.php">Program Ekle</a><a href="showdoctorschedule.php">Programlar</a></nav></header><main class="admin-wrap"><div class="page-head"><div><span class="admin-eyebrow">DOKTOR PROGRAMI</span><h1>Doktoru kliniğe ata</h1><p>Doktorun hangi klinikte, hangi gün ve saatlerde çalışacağını belirleyin.</p></div><a class="admin-button secondary" href="showdoctorschedule.php">Programları Gör</a></div><section class="admin-card form-card"><?php if($message):?><div class="alert <?php echo $type;?>"><?php echo htmlspecialchars($message);?></div><?php endif;?><form method="post"><div class="form-grid"><div class="field"><label for="city-list">Şehir</label><select id="city-list"><option value="">Şehir seçin</option><?php foreach($cities as $city):?><option value="<?php echo htmlspecialchars($city);?>"><?php echo htmlspecialchars($city);?></option><?php endforeach;?></select></div><div class="field"><label for="clinic-list">Klinik</label><select name="clinic" id="clinic-list" required><option value="">Önce şehir seçin</option></select></div><div class="field full"><label for="doctor-list">Doktor</label><select name="doctor" id="doctor-list" required><option value="">Önce şehir seçin</option></select></div><div class="field full"><label>Çalışma günleri</label><div class="days"><?php foreach($dayMap as $value=>$label):?><label class="day"><input type="checkbox" value="<?php echo $value;?>" name="daylist[]"> <?php echo $label;?></label><?php endforeach;?></div><div class="hint">Birden fazla gün seçerek aynı saat aralığını toplu ekleyebilirsiniz.</div></div><div class="field"><label for="starttime">Başlangıç saati</label><input id="starttime" type="time" name="starttime" required></div><div class="field"><label for="endtime">Bitiş saati</label><input id="endtime" type="time" name="endtime" required></div></div><div class="form-actions"><a class="admin-button secondary" href="mainpage.php">İptal</a><button class="admin-button" type="submit" name="Submit">Programı Kaydet</button></div></form></section></main><script>function load(url,data,target){fetch(url,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams(data)}).then(r=>r.text()).then(html=>document.getElementById(target).innerHTML=html).catch(()=>document.getElementById(target).innerHTML='<option value="">Liste yüklenemedi</option>')}document.getElementById('city-list').addEventListener('change',function(){load('getclinic.php',{city:this.value},'clinic-list');load('getdoctorregion.php',{city:this.value},'doctor-list')});</script></body></html>